INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('about','About FpiUpdates','About','<h2>Our story</h2><p>FpiUpdates began as an independent update and blog website built by Odewaye Mayomi Peter using PHP, HTML, CSS and JavaScript. It gained recognition among the Ilaro community between 2022 and 2024.</p><h2>A new chapter</h2><p>The revived platform brings conversations, articles and community connections together. We are starting with Ilaro while welcoming people beyond campus. FpiUpdates is independent and is not an official school or government portal.</p><h2>Our founder</h2><p>Odewaye Mayomi Peter founded FpiUpdates and OMPPEAK Technology. He is a Computer Engineering graduate of Federal Polytechnic Ilaro.</p>','<h2>Our story</h2><p>FpiUpdates began as an independent update and blog website built by Odewaye Mayomi Peter using PHP, HTML, CSS and JavaScript. It gained recognition among the Ilaro community between 2022 and 2024.</p><h2>A new chapter</h2><p>The revived platform brings conversations, articles and community connections together. We are starting with Ilaro while welcoming people beyond campus. FpiUpdates is independent and is not an official school or government portal.</p><h2>Our founder</h2><p>Odewaye Mayomi Peter founded FpiUpdates and OMPPEAK Technology. He is a Computer Engineering graduate of Federal Polytechnic Ilaro.</p>','About FpiUpdates',CURRENT_TIMESTAMP,0,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help','Help Centre','Getting started','<h2>Find help</h2><p>Browse the topics below for account access, posting, verification and safety. Some features may be disabled during the beta.</p>','<h2>Find help</h2><p>Browse the topics below for account access, posting, verification and safety. Some features may be disabled during the beta.</p>','Help Centre',CURRENT_TIMESTAMP,1,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('faq','Frequently asked questions','Getting started','<h2>Is FpiUpdates an official school platform?</h2><p>No. FpiUpdates is an independent community platform. Confirm institutional fees, admissions and deadlines through official sources.</p><h2>Do I need a verification badge?</h2><p>No. Identity verification is optional and is separate from confirming your email.</p><h2>Must I complete my profile?</h2><p>No. You can dismiss the profile completion card. Optional private details do not affect profile completion.</p>','<h2>Is FpiUpdates an official school platform?</h2><p>No. FpiUpdates is an independent community platform. Confirm institutional fees, admissions and deadlines through official sources.</p><h2>Do I need a verification badge?</h2><p>No. Identity verification is optional and is separate from confirming your email.</p><h2>Must I complete my profile?</h2><p>No. You can dismiss the profile completion card. Optional private details do not affect profile completion.</p>','Frequently asked questions',CURRENT_TIMESTAMP,2,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-verification','Verification on FpiUpdates','Identity & safety','<h2>What the green badge means</h2><p>FpiUpdates has reviewed the account identity or its authority to represent an organisation. It does not endorse content or guarantee transactions.</p><h2>Who can apply</h2><p>Public-interest accounts and genuine community contributors may apply. We review authenticity, public or community relevance, activity and account standing. There is no fixed follower threshold or fee at launch. Email confirmation alone does not qualify an account.</p><h2>Evidence and decisions</h2><p>Provide official public website references and an explanation of your identity or representative authority. Do not upload ID documents, passwords or private records to the request form. Staff may request more information. Track decisions in Settings → Verification. Use an appeal request to challenge a decision.</p><h2>Changes and subscriptions</h2><p>Changing your username or display name places an existing badge into review. Badges may be suspended or revoked for impersonation or fraudulent evidence. Subscriptions are not currently part of identity verification.</p>','<h2>What the green badge means</h2><p>FpiUpdates has reviewed the account identity or its authority to represent an organisation. It does not endorse content or guarantee transactions.</p><h2>Who can apply</h2><p>Public-interest accounts and genuine community contributors may apply. We review authenticity, public or community relevance, activity and account standing. There is no fixed follower threshold or fee at launch. Email confirmation alone does not qualify an account.</p><h2>Evidence and decisions</h2><p>Provide official public website references and an explanation of your identity or representative authority. Do not upload ID documents, passwords or private records to the request form. Staff may request more information. Track decisions in Settings → Verification. Use an appeal request to challenge a decision.</p><h2>Changes and subscriptions</h2><p>Changing your username or display name places an existing badge into review. Badges may be suspended or revoked for impersonation or fraudulent evidence. Subscriptions are not currently part of identity verification.</p>','Verification on FpiUpdates',CURRENT_TIMESTAMP,3,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-usernames','Usernames, reservations and claims','Identity & safety','<h2>Choosing a username</h2><p>Use 3–30 lowercase letters, numbers or underscores. Unavailable names may be occupied or protected. Essential system names cannot be registered.</p><h2>Claims</h2><p>Request a username review in Settings → Verification. A claim never guarantees a transfer. A company or public figure cannot automatically displace a legitimate existing user.</p><h2>Changing your handle</h2><p>Your content and account remain yours. A former handle is protected for 30 days, or longer for a reserved name. While protected, old profile links resolve to your current account. Links and mentions after expiry may no longer resolve to you.</p>','<h2>Choosing a username</h2><p>Use 3–30 lowercase letters, numbers or underscores. Unavailable names may be occupied or protected. Essential system names cannot be registered.</p><h2>Claims</h2><p>Request a username review in Settings → Verification. A claim never guarantees a transfer. A company or public figure cannot automatically displace a legitimate existing user.</p><h2>Changing your handle</h2><p>Your content and account remain yours. A former handle is protected for 30 days, or longer for a reserved name. While protected, old profile links resolve to your current account. Links and mentions after expiry may no longer resolve to you.</p>','Usernames, reservations and claims',CURRENT_TIMESTAMP,4,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-email','Confirm your email and sign in','Account access','<h2>Confirm before entering</h2><p>After creating an email/password account, check the address shown on the verification screen. Open the email and confirm using its link. Then continue to the feed.</p><h2>No message?</h2><p>Check Spam or Junk and the spelling of your email. Use Resend on the verification screen; resend has a cooldown. You can correct an unverified address using your current password.</p><h2>Google sign-in</h2><p>Google sign-in skips separate email confirmation only when the backend validates that Google verified the address. Use your existing account settings to connect Google when required.</p><h2>Password reset</h2><p>Use Forgot password on the sign-in page. Verification and reset links work once and expire. Never share them.</p>','<h2>Confirm before entering</h2><p>After creating an email/password account, check the address shown on the verification screen. Open the email and confirm using its link. Then continue to the feed.</p><h2>No message?</h2><p>Check Spam or Junk and the spelling of your email. Use Resend on the verification screen; resend has a cooldown. You can correct an unverified address using your current password.</p><h2>Google sign-in</h2><p>Google sign-in skips separate email confirmation only when the backend validates that Google verified the address. Use your existing account settings to connect Google when required.</p><h2>Password reset</h2><p>Use Forgot password on the sign-in page. Verification and reset links work once and expire. Never share them.</p>','Confirm your email and sign in',CURRENT_TIMESTAMP,5,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-posting','Posts and conversations','Using FpiUpdates','<h2>Posting</h2><p>Posts and replies have a 280-character limit. Use @username for mentions and #topic for hashtags. Availability of media, articles and other features depends on current feature settings.</p><h2>Threads and replies</h2><p>Reply to the specific post you mean. Author continuations and replies are connected to their parent posts. Quotes add your own comment while retaining a reference to the original post.</p>','<h2>Posting</h2><p>Posts and replies have a 280-character limit. Use @username for mentions and #topic for hashtags. Availability of media, articles and other features depends on current feature settings.</p><h2>Threads and replies</h2><p>Reply to the specific post you mean. Author continuations and replies are connected to their parent posts. Quotes add your own comment while retaining a reference to the original post.</p>','Posts and conversations',CURRENT_TIMESTAMP,6,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-safety','Reporting, blocking and appeals','Identity & safety','<h2>Report a problem</h2><p>Use the three-dot menu on a post to report harmful content. Use Settings → Verification to submit impersonation reports with the username and public evidence. Block and mute controls are available in account and post menus.</p><h2>Review and appeals</h2><p>Reports are reviewed by authorised staff. An approved report may require a separate moderation action; it is not an automatic account transfer. Use an appeal request and include the decision reference if you believe a mistake was made.</p><h2>Urgent situations</h2><p>FpiUpdates is not an emergency service. Do not share passwords, payment codes or sensitive identity documents. Verify payment instructions independently.</p>','<h2>Report a problem</h2><p>Use the three-dot menu on a post to report harmful content. Use Settings → Verification to submit impersonation reports with the username and public evidence. Block and mute controls are available in account and post menus.</p><h2>Review and appeals</h2><p>Reports are reviewed by authorised staff. An approved report may require a separate moderation action; it is not an automatic account transfer. Use an appeal request and include the decision reference if you believe a mistake was made.</p><h2>Urgent situations</h2><p>FpiUpdates is not an emergency service. Do not share passwords, payment codes or sensitive identity documents. Verify payment instructions independently.</p>','Reporting, blocking and appeals',CURRENT_TIMESTAMP,7,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-notifications','Notifications and installing the app','Using FpiUpdates','<h2>Notifications</h2><p>In-app notifications and device push permissions are separate. Enable device notifications in Settings on a supported browser. Delivery depends on permission, your device and server availability.</p><h2>Installation</h2><p>Use Install FpiUpdates or visit /install. On iPhone or iPad, use Safari → Share → Add to Home Screen. Installation requires your action. Cross-browser installation detection is limited.</p>','<h2>Notifications</h2><p>In-app notifications and device push permissions are separate. Enable device notifications in Settings on a supported browser. Delivery depends on permission, your device and server availability.</p><h2>Installation</h2><p>Use Install FpiUpdates or visit /install. On iPhone or iPad, use Safari → Share → Add to Home Screen. Installation requires your action. Cross-browser installation detection is limited.</p>','Notifications and installing the app',CURRENT_TIMESTAMP,8,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","publishedHtml","publishedTitle","effectiveAt","position","updatedAt") VALUES ('help-contact','Contact and support','Support','<h2>Account help</h2><p>Use account recovery for access problems, the post report menu for harmful posts, or Settings → Verification for username, identity and impersonation requests.</p><h2>Support contact</h2><p>A public support mailbox has not been configured in this document. The platform operator must add a monitored contact route here before public launch. Never send passwords or verification tokens to support.</p>','<h2>Account help</h2><p>Use account recovery for access problems, the post report menu for harmful posts, or Settings → Verification for username, identity and impersonation requests.</p><h2>Support contact</h2><p>A public support mailbox has not been configured in this document. The platform operator must add a monitored contact route here before public launch. Never send passwords or verification tokens to support.</p>','Contact and support',CURRENT_TIMESTAMP,9,CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","updatedAt") VALUES ('privacy','Privacy Policy','Policies','<p>Complete the operator identity, monitored contact route, processing purposes and legal bases, service providers, retention periods, data rights procedures and applicable privacy arrangements before publishing. This is a draft, not a completed privacy policy.</p>',CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","updatedAt") VALUES ('terms','Terms of Service','Policies','<p>Complete operator details, eligibility, account and content rules, moderation and appeals, intellectual property, service availability, applicable law and dispute arrangements before publishing. This is a draft requiring review.</p>',CURRENT_TIMESTAMP);
INSERT INTO "SiteDocument" ("slug","title","category","draftHtml","updatedAt") VALUES ('guidelines','Community Guidelines','Policies','<p>Respect others. No scams, deceptive impersonation, harassment, threats or sharing private information without permission. Verify institutional payment and admission instructions independently. Reports may lead to restrictions; appeals are available.</p>',CURRENT_TIMESTAMP);
INSERT INTO "SiteDocumentVersion" ("id", "slug", "title", "html", "effectiveAt", "createdAt") SELECT gen_random_uuid(), "slug", "publishedTitle", "publishedHtml", "effectiveAt", CURRENT_TIMESTAMP FROM "SiteDocument" WHERE "publishedHtml" IS NOT NULL;
