ALTER TABLE "User" ADD COLUMN "identityStatus" VARCHAR(12) NOT NULL DEFAULT 'NONE', ADD COLUMN "identityCategory" VARCHAR(20), ADD COLUMN "identityVerifiedAt" TIMESTAMP(3), ADD COLUMN "profileCompletionDismissed" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "UsernameHold" ("username" VARCHAR(30) PRIMARY KEY, "ownerId" UUID, "reason" VARCHAR(500) NOT NULL, "redirect" BOOLEAN NOT NULL DEFAULT false, "expiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IdentityRequest" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "kind" VARCHAR(16) NOT NULL, "category" VARCHAR(20) NOT NULL, "username" VARCHAR(30), "evidence" VARCHAR(4000) NOT NULL, "status" VARCHAR(12) NOT NULL DEFAULT 'PENDING', "decision" VARCHAR(1000), "reviewedById" UUID REFERENCES "User"("id") ON DELETE SET NULL, "reviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "IdentityRequest_userId_createdAt_idx" ON "IdentityRequest"("userId", "createdAt");
CREATE INDEX "IdentityRequest_status_createdAt_idx" ON "IdentityRequest"("status", "createdAt");
CREATE TABLE "AccountNotice" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "message" VARCHAR(1000) NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AccountNotice_userId_createdAt_idx" ON "AccountNotice"("userId", "createdAt");
CREATE TABLE "SiteDocument" ("slug" VARCHAR(100) PRIMARY KEY, "title" VARCHAR(160) NOT NULL, "category" VARCHAR(80) NOT NULL, "draftHtml" TEXT NOT NULL, "publishedHtml" TEXT, "publishedTitle" VARCHAR(160), "effectiveAt" TIMESTAMP(3), "position" INTEGER NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SiteDocumentVersion" ("id" UUID PRIMARY KEY, "slug" VARCHAR(100) NOT NULL, "title" VARCHAR(160) NOT NULL, "html" TEXT NOT NULL, "effectiveAt" TIMESTAMP(3) NOT NULL, "publishedById" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SiteDocumentVersion_slug_createdAt_idx" ON "SiteDocumentVersion"("slug", "createdAt");
UPDATE "Role" SET "permissions" = array_cat("permissions", ARRAY['usernames.manage','verification.manage','pages.edit','pages.publish']::text[]) WHERE "key" = 'administrator';

